<?php require 'includes/auth.php';require 'config/database.php';require 'includes/csrf.php';if($_SERVER['REQUEST_METHOD']==='POST'){check();$pdo->prepare('INSERT INTO cases(prisoner_id,case_number,offense,court_name,sentence_start,sentence_end,status) VALUES(?,?,?,?,?,?,?)')->execute([$_POST['prisoner_id'],trim($_POST['case_number']),trim($_POST['offense']),trim($_POST['court_name']),$_POST['sentence_start'],$_POST['sentence_end'],trim($_POST['status'])]);header('Location: cases.php');exit;}$rows=$pdo->query('SELECT * FROM cases ORDER BY id DESC')->fetchAll();$title='Cases';require 'includes/header.php';?><div class="row g-4"><div class="col-lg-4"><div class="box"><h4>Add Cases</h4><form method="post"><input type="hidden" name="token" value="<?=token()?>"><label class="form-label mt-2">Prisoner ID</label><input class="form-control" type="number" name="prisoner_id" required><label class="form-label mt-2">Case Number</label><input class="form-control" type="text" name="case_number" required><label class="form-label mt-2">Offense</label><input class="form-control" type="text" name="offense" required><label class="form-label mt-2">Court</label><input class="form-control" type="text" name="court_name" required><label class="form-label mt-2">Start Date</label><input class="form-control" type="date" name="sentence_start" required><label class="form-label mt-2">End Date</label><input class="form-control" type="date" name="sentence_end" required><label class="form-label mt-2">Status</label><input class="form-control" type="text" name="status" required><button class="btn btn-primary mt-3">Save</button></form></div></div><div class="col-lg-8"><div class="box"><h2>Cases</h2><div class="table-responsive"><table class="table"><tr><th>Prisoner ID</th><th>Case Number</th><th>Offense</th><th>Court</th><th>Start Date</th><th>End Date</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['prisoner_id'])?></td><td><?=htmlspecialchars($r['case_number'])?></